// Isolation test (OS-12) — construct Reachability with its declared inputs and nothing else,
// then exercise every public operation. (Generated by new-object.py, rewritten for strict
// TypeScript - MF-21, MF-22.)
import { describe, expect, it } from "vitest";
import { height, noSubject, type RecordHeight, type UnknownValue } from "../src/kernel/index.js";
import { CurrencyOrder, type Currency, type Unit } from "../src/catalog/index.js";
import { CommitmentLedger, type Commitment } from "../src/facts/index.js";
import { Reachability, type CommitmentFold } from "../src/reachability/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";

const u = "u1" as Unit;
const order = new CurrencyOrder({ currencies: ["c0", "c1"] });
const [c0, c1] = order.currencies() as readonly [Currency, Currency];

/** A fold where u has committed at c0. */
function committed(): { fold: CommitmentFold; at: RecordHeight } {
  const record = inMemoryRecord();
  const ledger = new CommitmentLedger({ record, invalidations: { isInvalidated: () => false } });
  return { fold: ledger, at: ledger.commit(u, c0, "HUMAN").at };
}
const nothing: CommitmentFold = { effectiveCommitment: (): Commitment | UnknownValue => noSubject() };

describe("Reachability in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new Reachability({ commitments: nothing } as never)).toThrow();
    expect(() => new Reachability({ currencies: order } as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new Reachability({ currencies: {} as never, commitments: nothing })).toThrow();
    expect(() => new Reachability({ currencies: order, commitments: {} as never })).toThrow();
  });

  it("of answers differently when commitments differs", () => {
    const { fold, at } = committed();
    const a = new Reachability({ currencies: order, commitments: fold }).of(u, c1).compute(at);
    const b = new Reachability({ currencies: order, commitments: nothing }).of(u, c1).compute(at);
    expect(a).not.toEqual(b);
  });

  it("of answers differently when currencies differs", () => {
    const { fold, at } = committed();
    const a = new Reachability({ currencies: order, commitments: nothing }).of(u, c1).compute(at);
    const flat = { predecessors: () => [] };
    const b = new Reachability({ currencies: flat, commitments: nothing }).of(u, c1).compute(at);
    expect(a).not.toEqual(b);
    expect(height(1)).toBeDefined();
  });
});
